<?php
namespace Tests\Feature;
use App\Models\{Employee,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Laravel\Sanctum\Sanctum; use Tests\TestCase;
class EvaluationApiTest extends TestCase {use RefreshDatabase; public function test_score_is_calculated_automatically():void{$user=User::factory()->create();$employee=Employee::factory()->create();$user->givePermissionTo(['create evaluations','view evaluations']);Sanctum::actingAs($user);$response=$this->postJson('/api/evaluations',['employee_id'=>$employee->id,'evaluation_date'=>'2026-09-03','period_start'=>'2026-01-01','period_end'=>'2026-06-30','skills_score'=>4,'soft_skills_score'=>3,'management_score'=>5]);$response->assertCreated()->assertJsonPath('data.overall_score','4.00');} public function test_invalid_score_is_rejected():void{$user=User::factory()->create();$employee=Employee::factory()->create();$user->givePermissionTo('create evaluations');Sanctum::actingAs($user);$this->postJson('/api/evaluations',['employee_id'=>$employee->id,'evaluation_date'=>'2026-09-03','period_start'=>'2026-01-01','period_end'=>'2026-06-30','skills_score'=>6])->assertStatus(422);}}
